import os
import re

import requests
from bs4 import BeautifulSoup
from requests.adapters import HTTPAdapter
from urllib3 import disable_warnings
from urllib3.exceptions import InsecureRequestWarning
from urllib3.util.retry import Retry
from taf.rfrl.utilities.settings import SVN_LOGIN, SVN_PASSWORD, CRACOW_PROXY


class URLConnection:
    """
    Class allows to create session and get response from URL.
    """

    def __init__(self, retry=3, timeout=30, http_proxies=None, https_proxies=None, stream=True, verify=False,
                 login=None, password=None):
        """
        Constructor.
        :param retry: number of retries before failure
        :param timeout: time in seconds
        :param http_proxies: necessary http proxy addresses
        :param https_proxies: necessary https proxy addresses
        :param stream: If set True read data as it arrives, if False data is returned as a single chunk. Default True.
        :param verify:
        :param login: login for authentication.
        :param password: password for authentication.
        """
        self.retry = Retry(total=retry, backoff_factor=0.1)
        self.timeout = timeout
        self.proxies = {'http': http_proxies, "https": https_proxies} if https_proxies or http_proxies else None
        self.stream = stream
        self.verify = verify
        self.login = login
        self.password = password
        self.session = None

    def connect(self):
        """
        Creates session object.
        :return: nothing
        """
        disable_warnings(InsecureRequestWarning)
        with requests.Session() as session:
            session.mount('https://', HTTPAdapter(max_retries=self.retry))
            if self.login and self.password:
                session.auth = (self.login, self.password)
        self.session = session

    def get(self, url):
        """
        Gets response from given URL.
        :param url: URL address.
        :return: Response object
        """
        if self.session is None:
            raise URLConnectionError("no connection, use connect to create connection.")
        response = self.session.get(url, timeout=self.timeout, proxies=self.proxies, stream=self.stream,
                                    verify=self.verify)
        response.raise_for_status()
        return response

    def get_url_content(self, url):
        response = self.get(url)
        return BeautifulSoup(response.text, "xml")

    def download_file(self, url, file_path, file_name):
        response = self.get(url)
        file_size = int(response.headers.get('Content-Length', 0))
        downloaded_size = 0
        with open(os.path.join(file_path, file_name), 'wb') as fd:
            for chunk in response.iter_content(chunk_size=8192):
                fd.write(chunk)
                downloaded_size += len(chunk)
        if downloaded_size != file_size:
            raise URLConnectionError("Downloaded file size is different than expected")

    @staticmethod
    def adjust_url(url):
        if url[-1] != "/":
            url += "/"
        return url


class SVNDownloader(URLConnection):

    def __init__(self, retry=3, timeout=30, stream=True, verify=False, http_proxies=None,
                 https_proxies=CRACOW_PROXY, login=SVN_LOGIN, password=SVN_PASSWORD):
        super(SVNDownloader, self).__init__(retry, timeout, http_proxies, https_proxies, stream, verify, login,
                                            password)
        self.connect()

    @staticmethod
    def get_all_files_names(content):
        return [file["name"] for file in content.find_all('file')]

    @staticmethod
    def get_all_dirs_names(content):
        return [file["name"] for file in content.find_all('dir')]

    def get_file_tree(self, url):
        base_content = self.get_url_content(url)
        tree = {url: {"files": self.get_all_files_names(base_content), "dirs": self.get_all_dirs_names(base_content)}}
        directories = tree[url]["dirs"]
        for i in range(len(directories)):
            directory = directories[i]
            new_url = self.adjust_url(url) + directory
            tree[url]["dirs"][i] = self.get_all_files_and_dirs(new_url, directory)
        return tree

    def get_all_files_and_dirs(self, url, directory):
        content = self.get_url_content(url)
        files = self.get_all_files_names(content)
        dirs = self.get_all_dirs_names(content)
        result = {directory: {"files": files, "dirs": dirs}}
        for i in range(len(dirs)):
            new_url = self.adjust_url(url) + dirs[i]
            result[directory]["dirs"][i] = self.get_all_files_and_dirs(new_url, dirs[i])
        return result

    def download_file_tree(self, tree, file_path):
        for key, value in tree.items():
            base_url = self.adjust_url(key)
            os.makedirs(file_path, exist_ok=True)
            for file in value['files']:
                self.download_file(base_url + file, file_path, file)
            for directory in value['dirs']:
                self.download_file_tree_recursively(directory, base_url, file_path)

    def download_file_tree_recursively(self, tree, base_url='', local_dir=''):
        for key, value in tree.items():
            new_base_url = self.adjust_url(base_url) + key + "/"
            new_local_dir = os.path.join(local_dir, key)
            os.makedirs(new_local_dir, exist_ok=True)
            for file in value['files']:
                self.download_file(new_base_url + file, new_local_dir, file)
            for directory in value['dirs']:
                self.download_file_tree_recursively(directory, new_base_url, new_local_dir)

    def find_files_in_tree(self, tree, regex):
        matched_files = []
        for key, value in tree.items():
            base_url = self.adjust_url(key)
            for file in value['files']:
                if re.match(regex, file):
                    matched_files.append(base_url + file)
            for directory in value['dirs']:
                matched_files.extend(self.find_files_in_tree_recursively(directory, regex, base_url))
        return matched_files

    def find_files_in_tree_recursively(self, tree, regex, base_url=''):
        matched_files = []
        for key, value in tree.items():
            new_base_url = base_url + key + '/'
            for file in value['files']:
                if re.match(regex, file):
                    matched_files.append(new_base_url + file)
            for directory in value['dirs']:
                matched_files.extend(self.find_files_in_tree_recursively(directory, regex, new_base_url))
        return matched_files


class URLConnectionError(Exception):
    pass
